"use client"
import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Checkbox } from "@atlas/ui-web/primitives/Checkbox/Checkbox"
import { mockSubmit } from "../../_shared/mockApi"
import { ERR_DECLINED, ERR_TIMEOUT, ORDER_TOTAL, type PaymentStepProps } from "../schema"

const digits = (v: string) => v.replace(/\D/g, "")
const formatCard = (v: string) => digits(v).slice(0, 16).replace(/(.{4})/g, "$1 ").trim()
const formatExpiry = (v: string) => {
  const d = digits(v).slice(0, 4)
  return d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}` : d
}

const expiryValid = (v: string) => {
  const m = /^(\d{2})\/(\d{2})$/.exec(v)
  return !!m && Number(m[1]) >= 1 && Number(m[1]) <= 12
}

const fieldStyle = { display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" } as const

export function Payment({ data, patch, goTo }: PaymentStepProps) {
  const [busy, setBusy] = useState(false)
  const [touched, setTouched] = useState<Record<string, boolean>>({})

  const cardOk = digits(data.cardNumber).length === 16
  const expOk = expiryValid(data.expiry)
  const cvcOk = data.cvc.length >= 3
  const valid = cardOk && expOk && cvcOk
  const touch = (k: string) => setTouched((t) => ({ ...t, [k]: true }))

  const submit = async () => {
    if (!valid) {
      setTouched({ card: true, expiry: true, cvc: true })
      return
    }
    setBusy(true)
    const timeout = data.simulateTimeout
    try {
      await mockSubmit(data, {
        delayMs: timeout ? 2400 : 1400,
        failRate: 1,
        errorMessage: timeout ? ERR_TIMEOUT : ERR_DECLINED,
      })
    } catch (e) {
      patch({ failure: (e as Error).message === ERR_TIMEOUT ? "timeout" : "declined" })
      goTo(1)
    } finally {
      setBusy(false)
    }
  }

  return (
    <form
      noValidate
      onSubmit={(e) => {
        e.preventDefault()
        if (!busy) void submit()
      }}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-5)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
      }}
    >
      <h1
        style={{
          margin: 0,
          fontSize: "var(--atlas-text-h2)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          lineHeight: "var(--atlas-line-height-snug)",
          color: "var(--atlas-foreground)",
        }}
      >
        Payment
      </h1>

      <div style={fieldStyle}>
        <Label htmlFor="pe-card" size="md" required invalid={touched.card && !cardOk}>Card number</Label>
        <Input
          id="pe-card"
          size="lg"
          inputMode="numeric"
          autoComplete="cc-number"
          placeholder="1234 5678 9012 3456"
          value={data.cardNumber}
          disabled={busy}
          invalid={touched.card && !cardOk}
          aria-describedby={touched.card && !cardOk ? "pe-card-err" : undefined}
          onChange={(e) => patch({ cardNumber: formatCard(e.target.value) })}
          onBlur={() => touch("card")}
        />
        {touched.card && !cardOk && (
          <FieldError id="pe-card-err">Enter the 16 digits on your card.</FieldError>
        )}
      </div>

      <div style={{ display: "flex", gap: "var(--atlas-spacing-3)" }}>
        <div style={{ ...fieldStyle, flex: 1 }}>
          <Label htmlFor="pe-expiry" size="md" required invalid={touched.expiry && !expOk}>Expiry</Label>
          <Input
            id="pe-expiry"
            size="lg"
            inputMode="numeric"
            autoComplete="cc-exp"
            placeholder="MM/YY"
            value={data.expiry}
            disabled={busy}
            invalid={touched.expiry && !expOk}
            aria-describedby={touched.expiry && !expOk ? "pe-expiry-err" : undefined}
            onChange={(e) => patch({ expiry: formatExpiry(e.target.value) })}
            onBlur={() => touch("expiry")}
          />
          {touched.expiry && !expOk && <FieldError id="pe-expiry-err">Use MM/YY.</FieldError>}
        </div>
        <div style={{ ...fieldStyle, flex: 1 }}>
          <Label htmlFor="pe-cvc" size="md" required invalid={touched.cvc && !cvcOk}>CVC</Label>
          <Input
            id="pe-cvc"
            size="lg"
            inputMode="numeric"
            autoComplete="cc-csc"
            placeholder="123"
            value={data.cvc}
            disabled={busy}
            invalid={touched.cvc && !cvcOk}
            aria-describedby={touched.cvc && !cvcOk ? "pe-cvc-err" : undefined}
            onChange={(e) => patch({ cvc: digits(e.target.value).slice(0, 4) })}
            onBlur={() => touch("cvc")}
          />
          {touched.cvc && !cvcOk && <FieldError id="pe-cvc-err">3 or 4 digits.</FieldError>}
        </div>
      </div>

      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "baseline",
          paddingBlock: "var(--atlas-spacing-3)",
          borderBlockStart: "var(--atlas-border-width-1) solid var(--atlas-border-subtle)",
          color: "var(--atlas-foreground)",
        }}
      >
        <span style={{ fontSize: "var(--atlas-text-body)", color: "var(--atlas-foreground-muted)" }}>Order total</span>
        <span style={{ fontSize: "var(--atlas-font-size-xl)", fontWeight: "var(--atlas-font-weight-bold)" }}>
          {ORDER_TOTAL}
        </span>
      </div>

      <Button type="submit" variant="primary" size="lg" loading={busy} style={{ inlineSize: "100%" }}>
        {busy ? "Processing…" : `Pay ${ORDER_TOTAL} now`}
      </Button>

      <div
        style={{
          paddingBlockStart: "var(--atlas-spacing-3)",
          borderBlockStart: "var(--atlas-border-width-1) dashed var(--atlas-border)",
        }}
      >
        <Checkbox
          size="sm"
          label="Prototype: simulate a network timeout"
          description="Off: the card is declined."
          checked={data.simulateTimeout}
          disabled={busy}
          onCheckedChange={(c) => patch({ simulateTimeout: c === true })}
        />
      </div>
    </form>
  )
}

function FieldError({ id, children }: { id: string; children: React.ReactNode }) {
  return (
    <span id={id} style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-danger)" }}>
      {children}
    </span>
  )
}

