          fontSize: "var(--atlas-text-h2)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          lineHeight: "var(--atlas-line-height-snug)",
          color: "var(--atlas-foreground)",
        }}
      >
        Payment
      </h1>

      <div style={fieldStyle}>
        <Label htmlFor="pe-card" size="md" required invalid={touched.card && !cardOk}>Card number</Label>
        <Input
          id="pe-card"
          size="lg"
          inputMode="numeric"
          autoComplete="cc-number"
          placeholder="1234 5678 9012 3456"
          value={data.cardNumber}
          disabled={busy}
          invalid={touched.card && !cardOk}
          aria-describedby={touched.card && !cardOk ? "pe-card-err" : undefined}
          onChange={(e) => patch({ cardNumber: formatCard(e.target.value) })}
          onBlur={() => touch("card")}
        />
        {touched.card && !cardOk && (
          <FieldError id="pe-card-err">Enter the 16 digits on your card.</FieldError>
        )}
      </div>

      <div style={{ display: "flex", gap: "var(--atlas-spacing-3)" }}>
        <div style={{ ...fieldStyle, flex: 1 }}>
          <Label htmlFor="pe-expiry" size="md" required invalid={touched.expiry && !expOk}>Expiry</Label>
          <Input
            id="pe-expiry"
            size="lg"
            inputMode="numeric"
            autoComplete="cc-exp"
            placeholder="MM/YY"
            value={data.expiry}
            disabled={busy}
            invalid={touched.expiry && !expOk}
            aria-describedby={touched.expiry && !expOk ? "pe-expiry-err" : undefined}
            onChange={(e) => patch({ expiry: formatExpiry(e.target.value) })}
            onBlur={() => touch("expiry")}
          />
          {touched.expiry && !expOk && <FieldError id="pe-expiry-err">Use MM/YY.</FieldError>}
        </div>
