"use client"
import { useEffect, useRef, useState } from "react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { mockSubmit } from "../../_shared/mockApi"
import { ORDER_TOTAL, type PaymentStepProps } from "../schema"

const COPY = {
  declined: {
    title: "Your card was declined",
    description:
      "Your bank didn't approve this payment. You haven't been charged. Check the details below, or try another card.",
  },
  timeout: {
    title: "We couldn't reach the payment service",
    description:
      "The connection timed out, so we don't know if the payment went through. You haven't been charged. Check your connection and retry.",
  },
} as const

export function Failure({ data, patch, next, goTo }: PaymentStepProps) {
  const [busy, setBusy] = useState(false)
  const [supportOpen, setSupportOpen] = useState(false)
  const headingRef = useRef<HTMLHeadingElement>(null)
  const kind = data.failure
  const copy = COPY[kind]
  const last4 = data.cardNumber.replace(/\D/g, "").slice(-4)

  useEffect(() => {
    headingRef.current?.focus()
  }, [])

  // Timeout: the details are fine, so retry in place without leaving the screen.
  const retryNow = async () => {
    setBusy(true)
    try {
      await mockSubmit(data, { delayMs: 1400 })
      patch({ simulateTimeout: false })
      next()
    } finally {
      setBusy(false)
    }
  }

  // Declined: same card may be corrected, so return to the form with the entries kept.
  const editCard = () => goTo(0)

  const useDifferentCard = () => {
    patch({ cardNumber: "", expiry: "", cvc: "" })
    goTo(0)
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-5)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
      }}
    >
      <h1
        ref={headingRef}
        tabIndex={-1}
        style={{
          margin: 0,
          fontSize: "var(--atlas-text-h2)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          lineHeight: "var(--atlas-line-height-snug)",
          color: "var(--atlas-foreground)",
          outline: "none",
        }}
      >
        Payment not completed
      </h1>

      <div role="alert">
        <Alert variant="danger" size="md" title={copy.title} description={copy.description} />
      </div>

      <dl
        style={{
          margin: 0,
          display: "grid",
          gridTemplateColumns: "auto 1fr",
          columnGap: "var(--atlas-spacing-4)",
          rowGap: "var(--atlas-spacing-2)",
          fontSize: "var(--atlas-text-body-sm)",
        }}
      >
        <dt style={{ color: "var(--atlas-foreground-muted)" }}>Card</dt>
        <dd style={{ margin: 0, textAlign: "end", color: "var(--atlas-foreground)" }}>
          {last4 ? `Ending in ${last4}` : "Not entered"}
        </dd>
        <dt style={{ color: "var(--atlas-foreground-muted)" }}>Expiry</dt>
        <dd style={{ margin: 0, textAlign: "end", color: "var(--atlas-foreground)" }}>{data.expiry || "—"}</dd>
        <dt style={{ color: "var(--atlas-foreground-muted)" }}>Order total</dt>
        <dd
          style={{
            margin: 0,
            textAlign: "end",
            fontWeight: "var(--atlas-font-weight-semibold)",
            color: "var(--atlas-foreground)",
          }}
        >
          {ORDER_TOTAL}
        </dd>
      </dl>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-3)" }}>
        {kind === "timeout" ? (
          <>
            <Button variant="primary" size="lg" loading={busy} onClick={retryNow} style={{ inlineSize: "100%" }}>
              {busy ? "Retrying…" : "Retry payment"}
            </Button>
            <Button variant="secondary" size="lg" disabled={busy} onClick={editCard} style={{ inlineSize: "100%" }}>
              Review card details
            </Button>
          </>
        ) : (
          <>
            <Button variant="primary" size="lg" onClick={editCard} style={{ inlineSize: "100%" }}>
              Try again
            </Button>
            <Button variant="secondary" size="lg" onClick={useDifferentCard} style={{ inlineSize: "100%" }}>
              Use a different card
            </Button>
          </>
        )}
        <Button
          variant="link"
          size="md"
          disabled={busy}
          aria-expanded={supportOpen}
          aria-controls="pe-support"
          onClick={() => setSupportOpen((o) => !o)}
        >
          Contact support
        </Button>
        {supportOpen && (
          <div id="pe-support">
            <Alert
              variant="info"
              size="sm"
              title="Support"
              description="In the real product this opens chat or a call. Mention the time of this attempt so they can find it."
            />
          </div>
        )}
      </div>
    </div>
  )
}

