          fontSize: "var(--atlas-text-h2)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          lineHeight: "var(--atlas-line-height-snug)",
          color: "var(--atlas-foreground)",
          outline: "none",
        }}
      >
        Payment not completed
      </h1>

      <div role="alert">
        <Alert variant="danger" size="md" title={copy.title} description={copy.description} />
      </div>

      <dl
        style={{
          margin: 0,
          display: "grid",
          gridTemplateColumns: "auto 1fr",
          columnGap: "var(--atlas-spacing-4)",
          rowGap: "var(--atlas-spacing-2)",
          fontSize: "var(--atlas-text-body-sm)",
        }}
      >
        <dt style={{ color: "var(--atlas-foreground-muted)" }}>Card</dt>
        <dd style={{ margin: 0, textAlign: "end", color: "var(--atlas-foreground)" }}>
          {last4 ? `Ending in ${last4}` : "Not entered"}
        </dd>
        <dt style={{ color: "var(--atlas-foreground-muted)" }}>Expiry</dt>
        <dd style={{ margin: 0, textAlign: "end", color: "var(--atlas-foreground)" }}>{data.expiry || "—"}</dd>
        <dt style={{ color: "var(--atlas-foreground-muted)" }}>Order total</dt>
        <dd
          style={{
            margin: 0,
            textAlign: "end",
            fontWeight: "var(--atlas-font-weight-semibold)",
            color: "var(--atlas-foreground)",
          }}
        >
          {ORDER_TOTAL}
        </dd>
      </dl>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-3)" }}>
        {kind === "timeout" ? (
          <>
            <Button variant="primary" size="lg" loading={busy} onClick={retryNow} style={{ inlineSize: "100%" }}>
              {busy ? "Retrying…" : "Retry payment"}
            </Button>
            <Button variant="secondary" size="lg" disabled={busy} onClick={editCard} style={{ inlineSize: "100%" }}>
              Review card details
            </Button>
          </>
        ) : (
          <>
            <Button variant="primary" size="lg" onClick={editCard} style={{ inlineSize: "100%" }}>
              Try again
            </Button>
            <Button variant="secondary" size="lg" onClick={useDifferentCard} style={{ inlineSize: "100%" }}>
              Use a different card
            </Button>
          </>
        )}
        <Button
          variant="link"
          size="md"
          disabled={busy}
          aria-expanded={supportOpen}
          aria-controls="pe-support"
          onClick={() => setSupportOpen((o) => !o)}
        >
          Contact support
        </Button>
        {supportOpen && (
          <div id="pe-support">
            <Alert
              variant="info"
              size="sm"
              title="Support"
              description="In the real product this opens chat or a call. Mention the time of this attempt so they can find it."
            />
          </div>
        )}
      </div>
    </div>
  )
}
